figure.sourcecode:
; The JSON messages of the attest-* resources (RFC 8610; RFC 8259). ; A byte string is carried as a text string holding its unpadded ; base64url encoding (RFC 4648, Section 5), as the control .b64u of ; RFC 9741 defines.
attestation-initiation-response = { initiation-freshness, initiation-mode, ? acceptable_evidence: [+ text], }
initiation-freshness = ( freshness_kind: "present-nonce", handle: text .b64u (bytes .size (16..64)), ? expires_in: uint, // freshness_kind: "present-epoch", handle: text .b64u (bytes .size (8..64)), ? expires_in: uint, // freshness_kind: "absent-timestamp", ? max_age: uint, // freshness_kind: "absent-epoch" / "absent-none", )
initiation-mode = ( mode: "enroll", acceptable_csk: [+ text], // mode: "retrieve", acceptable_cek: [+ text], )
attested-enrollment-request = { request-common, request-freshness, csr: text .b64u bytes, }
attested-retrieval-request = { request-common, request-freshness, cek_pub: text .b64u bytes, }
request-common = ( target: text, ? credential_type: text, evidence: text .b64u bytes, ? profile: text, binding: binding, ? credential_hint: text, )
request-freshness = ( freshness_kind: "absent-none" // freshness_kind: "absent-timestamp", handle: text .b64u (bytes .size 8), // freshness_kind: "absent-epoch" / "present-epoch", handle: text .b64u (bytes .size (8..64)), // freshness_kind: "present-nonce", handle: text .b64u (bytes .size (16..64)), )
binding = { method: "binding-input", hash: "sha512", }

figure.artwork:
NOTE: '\' line wrapping per RFC 8792
POST /.well-known/est/attest-retrieve HTTP/1.1 Host: est.tacra.example Content-Type: application/est-attest-retrieve+json
{ "target": "https://ledger-nonce.tacra.example", "credential_type": "api-key", "freshness_kind": "present-nonce", "handle": "JRAAJxYwTJ-tsqU1Kqk_PQpA...", "cek_pub": "MFkwEwYHKoZIzj0CAQYIKoZI...", "evidence": "o2dhdXhibG9iWRKbY9p1jeZk...", "binding": { "method": "binding-input", "hash": "sha512" }, "profile": "application/vnd.veraison.tsm-report+cbor", "credential_hint": "payments.workload.tacra.example" }
HTTP/1.1 200 OK Content-Type: application/est-attest-bundle+json
{ "container": "hpke-base", "suite": { "kem": "DHKEM(P-256, HKDF-SHA256)", "kdf": "HKDF-SHA256", "aead": "AES-256-GCM" }, "enc": "BFR-7sH5nfSJ7HuGs5K0dydE...", "ciphertext": "FrhDDRwvpBSZgk-1tjX-IBHR...", "aad": { "group_id": "0156b1ec5fc72a6ccc6c04b33e23cb114c9e19979cd3fe68bdd\ 7e9495544a46c", "target": "aHR0cHM6Ly9sZWRnZXItbm9uY2UudGFjcmEuZXhhbXBsZQ", "handle": "JRAAJxYwTJ-tsqU1Kqk_PQpA...", "credential_hint": "payments.workload.tacra.example" } }
